package com.amplayer.portable;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import org.json.*;import java.io.*;import java.nio.*;
public class CarColdStartInstrumentation extends Instrumentation {
 private String phase;@Override public void onCreate(Bundle b){super.onCreate(b);phase=b.getString("phase","verify");start();}
 @Override public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();try{
 if("prepare".equals(phase)){int bytes=1920000;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"JAMPlayer-Car-Cold-Test.wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/JAMPlayerCarTest");Uri uri=c.getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);try(OutputStream out=c.getContentResolver().openOutputStream(uri)){out.write(wave.array());}JSONObject song=new JSONObject().put("name","Cold start test").put("type","local").put("path",uri.toString()).put("playbackContext","local");JSONObject state=new JSONObject().put("stations",new JSONArray()).put("favorites",new JSONArray()).put("localFiles",new JSONArray().put(song)).put("playlists",new JSONArray()).put("volume",0).put("autoUpdate",false).put("carAutoResume",true).put("carResumeDelaySec",0).put("lastPlayed",song);Store.save(c,state.toString());CarMemory.clear(c);Activity a=startActivitySync(new Intent(Intent.ACTION_MAIN).setClass(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));boolean playing=false;for(int n=0;n<100;n++){if(new JSONObject(PlaybackService.status()).optBoolean("playing")){playing=true;break;}Thread.sleep(100);}if(!playing)throw new Exception("Fixture did not play");runOnMainSync(()->PlaybackService.seek(37500));Thread.sleep(600);runOnMainSync(PlaybackService::carCheckpoint);long pos=CarMemory.read(c).optLong("position");if(pos<37000)throw new Exception("Fixture checkpoint failed");c.getSharedPreferences("car-cold-test",0).edit().putString("uri",uri.toString()).putLong("position",pos).commit();result.putString("prepared","PASS live local audio checkpoint persisted near 37 seconds; PID="+android.os.Process.myPid());runOnMainSync(a::finish);
 }else{String uri=c.getSharedPreferences("car-cold-test",0).getString("uri","");long expected=c.getSharedPreferences("car-cold-test",0).getLong("position",0);if(expected<37000)throw new Exception("Missing persisted checkpoint");Activity a=startActivitySync(new Intent(Intent.ACTION_MAIN).setClass(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));JSONObject s=new JSONObject();for(int n=0;n<100;n++){s=new JSONObject(PlaybackService.status());if(s.optBoolean("playing"))break;Thread.sleep(100);}if(!s.optBoolean("playing")||!uri.equals(s.getJSONObject("item").optString("path"))||s.optLong("position")<expected-500||s.optLong("position")>expected+6000)throw new Exception("Process resume failed: "+s);result.putString("coldProcess","PASS actual process kill/relaunch resumed saved local track at "+s.optLong("position")+" ms; PID="+android.os.Process.myPid());runOnMainSync(()->{PlaybackService.carForget(c);c.stopService(new Intent(c,PlaybackService.class));a.finish();});c.getContentResolver().delete(Uri.parse(uri),null,null);c.getSharedPreferences("car-cold-test",0).edit().clear().commit();Store.save(c,new JSONObject().toString());}
 result.putString("result","PASS");}catch(Throwable e){result.putString("failure",e.toString());}finish(result.containsKey("failure")?0:-1,result);}
}
